/* Texture quadrillée clinique ultra légère */
.bg-clinical-grid-dark {
  background-image: radial-gradient(#1E293B 1px, transparent 1px), linear-gradient(to right, #121A24 1px, transparent 1px), linear-gradient(to bottom, #121A24 1px, transparent 1px);
  background-size: 24px 24px;
}
.bg-clinical-grid-light {
  background-image: radial-gradient(#CBD5E1 1px, transparent 1px), linear-gradient(to right, #F1F5F9 1px, transparent 1px), linear-gradient(to bottom, #F1F5F9 1px, transparent 1px);
  background-size: 24px 24px;
}

/* Animation Flamme de Série (Streak Pulse) */
@keyframes flame-pulse {
  0%, 100% {
    transform: scale(1) rotate(-1deg);
    filter: drop-shadow(0 0 12px rgba(245, 158, 11, 0.65));
  }
  50% {
    transform: scale(1.09) rotate(2deg);
    filter: drop-shadow(0 0 20px rgba(234, 88, 12, 0.9));
  }
}
.animate-flame {
  animation: flame-pulse 2.2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* Animation Ligne ECG / Battement Cardiaque */
@keyframes pulse-scan {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(200%); }
}
.animate-ecg-scan {
  animation: pulse-scan 3s ease-in-out infinite;
}

/* Effet de bordure néon clinique */
.clinical-border-glow {
  box-shadow: 0 0 0 1px var(--color-border), 0 8px 24px -4px rgba(16, 185, 129, 0.08);
}
.clinical-border-glow-dark {
  box-shadow: 0 0 0 1px #1E293B, 0 8px 30px -4px rgba(16, 185, 129, 0.12);
}
